void main()
{
    //由于这三个引脚默认高电平会导致点亮探照灯，所以程序中将引脚置低电平
    //设置P4口作为普通的IO口使用
    P4SW |= (1<<4);
    P4SW |= (1<<5);
    P4SW |= (1<<6);
    //设置P4口为强推挽输出模式
    P4M1 &= ~(1<<4);
    P4M1 &= ~(1<<5);
    P4M1 &= ~(1<<6);
    P4M0 |= (1<<4);
    P4M0 |= (1<<5);
    P4M0 |= (1<<6);
    LED_R=0;
    LED_G=0;
    LED_B=0;
    TMOD|=0X01;  //定时器0工作方式1
    TH0=0XFC;    //1ms定时，装入初值
    TL0=0X66;
    TR0=1; //启动T0工作
    ET0=1;   //允许T0中断
    TMOD|=0X10; //定时器1工作方式1
    TH1=0XFC;    //1ms定时，装入初值
    TL1=0X66;
    ET1=1;     //允许T1中断
    EA =1;     //开总中断
    //初始化超声波管脚
    TrigPin=0;
    //调用按键扫描函数
    key_scan();
    while(1)
    {
        measure_Distance();
        delay(100);
        if (distance > 35)
        {
            run(10, 10);            //当距离障碍物较远时全速前进
        }
        else if (distance >= 25 && distance <= 35)
        {
            run(5, 5);            //当快靠近障碍物时慢速前进
        }
        else if (distance < 25)
        {
            spin_right(400);        //当靠近障碍物时原地右转大约90度
            brake(1);
            measure_Distance();     //再次测试判断前方距离
            delay(100);
            if (distance >= 25)
            {
                run(5, 5);        //转弯后当前方距离大于25cm时前进
            }
            else if (distance < 25)
            {
                spin_left(800);     //转弯后前方距离小于25cm时向左原地转弯180度
                brake(1);
                measure_Distance(); //再次测试判断前方距离
                delay(100);
                if (distance >= 25)
                {
                    run(5, 5);     //转弯后当前方距离大于25cm时前进
                }
                else if (distance < 25)
                {
                    spin_left(400);  //转弯后前方距离小于25cm时向左原地转弯90度
                    brake(1);
                }
            }
        }
    }
}
