void Serial_Init()
{
    SCON=0x50;      //[bit6:5]SM1 SM2 = 1 0;[bit4]REN=1
    AUXR=0x11;      //[bit4]BRTR=1,允许独立波特率发生器运行;[bit0]SIBRS=1,
                    //独立波特率作为串口1的波特率发生器，此时定时器1释放
    BRT=0XFD;       //独特波特率发生器定时器（产生波特率9600）
    ES=1;//开串口中断
    EA=1;//开总中断
}

void uart_send_byte(unsigned char dat)
{
    SBUF = dat;          //把数据放到SBUF中
    while(TI == 0);      //未发送完毕就等待
    TI=0;                  //发送完毕后，要把TI重置0
}

void uart_send_string(unsigned char *str)
{
    while(*str != '\0')     //判断指针str是否指向字符串的末尾
    {
        uart_send_byte(*str);     //往串口上发送字符串
        str++; //指针自增，按照一个字节一个字节发送字符串
    }
}
