```c
void measure_Distance()
{
    unsigned char l;
    unsigned int h,y;
    ultrasonic_trigger();
    while(!EchoPin);   //触发超声波测距后，等待电平变成高电平，计时开始
    TR1 =1;
    while(EchoPin);   //超声波回波之后，等待电平变成低电平，计时结束
    TR1=0;
    l=TL1;
    h=TH1;
    y=(h<<8) +l;
    y=y-0xfc66;   //us部分
    distance=y+1000*count;//计算总时间，us部分+定时器计数的次数（每次1000us）
    TL1=0x66;
    TH1=0xfc;
    distance= 0.017*distance;//换算公式：us/58=cm 即0.017*us=cm
    TrigPin =0;
    count=0;
    return;
}
```

